@yuwata Either of these patches seems to resolve the issue.

This just processes the removal queue in `manager_free` after links are taken down.

```diff
diff --git a/src/network/networkd-manager.c b/src/network/networkd-manager.c
index 4ec4550caf..c17bf88b23 100644
--- a/src/network/networkd-manager.c
+++ b/src/network/networkd-manager.c
@@ -624,6 +624,8 @@ Manager* manager_free(Manager *m) {
         HASHMAP_FOREACH(link, m->links_by_index)
                 (void) link_stop_engines(link, true);
 
+        (void) manager_process_remove_requests(m);
+
         m->request_queue = ordered_set_free(m->request_queue);
         m->remove_request_queue = ordered_set_free(m->remove_request_queue);
 
```

And this takes down links in an exit handler instead of in `manager_free`.

```diff
diff --git a/src/network/networkd-manager.c b/src/network/networkd-manager.c
index 4ec4550caf..98c85cd7ee 100644
--- a/src/network/networkd-manager.c
+++ b/src/network/networkd-manager.c
@@ -431,6 +431,19 @@ static int manager_post_handler(sd_event_source *s, void *userdata) {
         return 0;
 }
 
+static int manager_exit_handler(sd_event_source *s, void *userdata) {
+        Link *link;
+
+        Manager *manager = ASSERT_PTR(userdata);
+
+        HASHMAP_FOREACH(link, manager->links_by_index)
+                (void) link_stop_engines(link, true);
+
+        (void) manager_post_handler(s, userdata);
+
+        return 0;
+}
+
 static int signal_terminate_callback(sd_event_source *s, const struct signalfd_siginfo *si, void *userdata) {
         Manager *m = ASSERT_PTR(userdata);
 
@@ -508,6 +521,10 @@ int manager_setup(Manager *m) {
         if (r < 0)
                 return r;
 
+        r = sd_event_add_exit(m->event, NULL, manager_exit_handler, m);
+        if (r < 0)
+                return r;
+
         r = manager_listen_fds(m, &rtnl_fd);
         if (r < 0)
                 return r;
@@ -614,16 +631,11 @@ int manager_new(Manager **ret, bool test_mode) {
 }
 
 Manager* manager_free(Manager *m) {
-        Link *link;
-
         if (!m)
                 return NULL;
 
         free(m->state_file);
 
-        HASHMAP_FOREACH(link, m->links_by_index)
-                (void) link_stop_engines(link, true);
-
         m->request_queue = ordered_set_free(m->request_queue);
         m->remove_request_queue = ordered_set_free(m->remove_request_queue);
 
```

I'm not really sure if either of these is a desirable solution. But they do fix the problem and *I believe* don't interfere with any other functionality. Feel free to use them.
